def _card(cid):
    return _CARDS.get(str(cid)) if isinstance(cid, int) else None

def _pv(c):
    return 2.0 if (c and c.get("ex")) else 1.0

def _eff(atk, my_c, opp_c):
    if not atk:
        return 0
    d = atk.get("d") or 0
    if opp_c and my_c and opp_c.get("wt") is not None and opp_c.get("wt") == my_c.get("pt"):
        d *= 2
    return d

def energy_covered(cost, energies):
    """能量匹配：cost 类型多重集（0=无色任意支付）；元素非 int 退化数量比"""
    if not cost:
        return True
    try:
        from collections import Counter
        if not all(isinstance(t, int) for t in cost):
            return len(energies or []) >= len(cost)
        need = Counter(t for t in cost if t != 0)
        have = Counter(e for e in (energies or []) if isinstance(e, int))
        for t, n in need.items():
            if have.get(t, 0) < n:
                return False
        leftover = len(energies or []) - sum(need.values())
        return leftover >= sum(1 for t in cost if t == 0)
    except Exception:
        return len(energies or []) >= len(cost)

def _can_ko(attacker, defender):
    if not isinstance(attacker, dict) or not isinstance(defender, dict):
        return False
    a_card = _card(attacker.get("id"))
    d_card = _card(defender.get("id"))
    if not a_card or not d_card:
        return False
    hp = defender.get("hp") or 999
    for aid in (a_card.get("at") or []):
        atk = _ATTACKS.get(str(aid))
        if atk and energy_covered(atk.get("e"), attacker.get("energies")) and _eff(atk, a_card, d_card) >= hp:
            return True
    return False

def agent(obs, config=None):
    sel = (obs or {}).get("select")
    if sel is None:
        return list(DEFAULT_DECK)
    opts = sel.get("option") or []
    mc = int(sel.get("maxCount") or 0)
    mn = int(sel.get("minCount") or 0)
    if not opts or mc <= 0:
        return []
    if sel.get("context") != 0:
        k = max(mn, min(1, mc)) if mn <= 1 else mn
        return list(range(min(k, len(opts))))
    cur = obs.get("current") or {}
    my_i = cur.get("yourIndex", 0) or 0
    players = cur.get("players") or []
    my = players[my_i] if len(players) > my_i else {}
    opp = players[1 - my_i] if len(players) > 1 - my_i else {}
    my_active = (my.get("active") or [None])[0]
    opp_active = (opp.get("active") or [None])[0]
    opp_card = _card(opp_active.get("id")) if isinstance(opp_active, dict) else None
    my_card = _card(my_active.get("id")) if isinstance(my_active, dict) else None
    my_prize_left = len(my.get("prize") or [])
    opp_prize_left = len(opp.get("prize") or [])

    doomed = 0.0
    if isinstance(opp_active, dict) and isinstance(my_active, dict):
        my_hp = my_active.get("hp") or 999
        for aid in ((opp_card or {}).get("at") or []):
            a = _ATTACKS.get(str(aid))
            if a and energy_covered(a.get("e"), opp_active.get("energies")) and _eff(a, opp_card, my_card) >= my_hp:
                doomed = 1.0
                break
    danger = 0.0
    if isinstance(opp_active, dict) and isinstance(my_active, dict):
        if _can_ko(opp_active, my_active):
            my_value = _pv(my_card)
            danger = 1.0 if opp_prize_left - my_value <= 0 else 0.4
    desperation = max(0.0, my_prize_left - opp_prize_left) / 6.0
    fatigue = max(0.0, (opp.get("deckCount") or 0) - (my.get("deckCount") or 0)) / 60.0

    scores = []
    for o in opts:
        if not isinstance(o, dict):
            scores.append(0.0); continue
        t = o.get("type"); s = 0.0
        if t == 13:
            a = _ATTACKS.get(str(o.get("attackId")))
            covered = energy_covered(a.get("e"), my_active.get("energies") if isinstance(my_active, dict) else []) if a else False
            if covered:
                eff = _eff(a, my_card, opp_card)
                opp_hp = (opp_active.get("hp") or 0) if isinstance(opp_active, dict) else 0
                s += W.get("covered", 0)
                if eff >= opp_hp > 0:
                    s += W.get("oneshot", 0) * _pv(opp_card)
                    taken = _pv(opp_card)
                    if my_prize_left - taken <= 0:
                        s += W.get("win_now", 0)
                    else:
                        retaliation = _can_ko(opp_active, my_active) or any(
                            _can_ko(b, my_active) for b in (opp.get("bench") or []) if isinstance(b, dict))
                        if not retaliation and my_prize_left - taken <= 2:
                            s += W.get("race_edge", 0)
                s += W.get("damage", 0) * eff / 100.0
                weakness_hit = (opp_card and my_card and opp_card.get("wt") is not None
                                and opp_card.get("wt") == my_card.get("pt"))
                if weakness_hit:
                    s += W.get("weakness_progress", 0) * eff / 100.0
                s += W.get("ko_desperation", 0) * desperation + W.get("fatigue_push", 0) * fatigue
            else:
                s -= 2.0
        elif t == 8: s += W.get("attach_progress", 0)
        elif t == 9: s += W.get("evolve", 0)
        elif t in (7, 10, 15): s += W.get("play", 0)
        elif t == 12:
            ex_risk = 1.0 if (doomed and my_card and my_card.get("ex")) else 0.0
            s += W.get("retreat_penalty", 0) + (W.get("retreat_escape", 0) if doomed else 0.0) + W.get("ex_retreat_boost", 0) * ex_risk + W.get("danger_flee", 0) * danger
        elif t == 14: s += W.get("end", 0)
        elif t == 11: s -= 0.5
        elif t == 1: s += 0.2
        elif t == 2: s -= 0.2
        scores.append(s)
    order = sorted(range(len(opts)), key=lambda i: -scores[i])
    out = order[:mc]
    if mn > 0:
        out = (out[:max(mn, min(len(out), mc))] + [i for i in range(len(opts)) if i not in out])[:mc]
    return out
